#include <stdio.h>
#include <stddef.h>

typedef int (*IntOp)(int);         /* a pointer to int f(int). */

int square(int x) { return x * x; }
int negate(int x) { return -x; }

void transform(int *v, size_t n, IntOp operation) {
    for (size_t i = 0; i < n; i++) v[i] = operation(v[i]);   /* callback. */
}

/* Adapter instead of an incompatible cast. */
double half(double x) { return x / 2; }
int half_int(int x) { return (int)half((double)x); }

int main(void) {
    int v[] = {1, 2, 3};
    transform(v, 3, square);       /* 1 4 9. */
    transform(v, 3, negate);       /* -1 -4 -9. */
    transform(v, 3, half_int);     /* 0 -2 -4: C division truncates toward zero. */
    for (size_t i = 0; i < 3; i++) printf("%d ", v[i]);
    return 0;
}
